      }
      continue;
    }

    if (inQualificationSection) {
      const cleanLine = rawLine.replace(/^[\s#*•\-\d\.]+\s*/, '').replace(/<[^>]+>/g, '').trim();

      if (cleanLine.length < 5 || cleanLine.length > 300) continue;

