  { name: 'REST APIs', pattern: /\b(?:rest|restful)(?:\s+apis?)?\b/i },
  { name: 'GraphQL', pattern: /\bgraphql\b/i },
  { name: 'Microservices', pattern: /\bmicroservices\b/i },
  { name: 'Object-Oriented Design', pattern: /\b(?:object[- ]oriented|oop|ood)\b/i },

  // Databases
